begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('cc280000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated')::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'explainer-'||n||'@test.local' from generate_series(10,15) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'explain-a','A'),(pg_temp.id(2),'explain-b','B');
insert into public.memberships(organization_id,user_id,role) values(pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'planner'),(pg_temp.id(1),pg_temp.id(12),'viewer'),(pg_temp.id(1),pg_temp.id(13),'branch_user'),(pg_temp.id(2),pg_temp.id(14),'owner'),(pg_temp.id(1),pg_temp.id(15),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone) values(pg_temp.id(20),pg_temp.id(1),'L1','One','branch','SA','Asia/Riyadh'),(pg_temp.id(21),pg_temp.id(1),'L2','Two','branch','SA','Asia/Riyadh');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(13),pg_temp.id(20));
insert into public.planning_runs(id,organization_id,location_id,request_id,from_date,to_date,kind,status,options,finished_at,result)
 select pg_temp.id(30+n),pg_temp.id(1),pg_temp.id(20+n),pg_temp.id(40+n),'2026-07-01','2026-10-01','policy','succeeded','{}',now(),'{}' from generate_series(0,1) n;
insert into public.inventory_policies(id,organization_id,run_id,location_id,forecast_id,item_id,item_code,unit,status,summary,evidence)
 select pg_temp.id(50+n),pg_temp.id(1),pg_temp.id(30+n),pg_temp.id(20+n),pg_temp.id(60),pg_temp.id(61),'PART-'||n,'EA','available','{}','{"method": "policy-v1", "options": {"lead_time": 3, "review_interval": 4, "service_level": "0.95"}, "forecast": {"run_id": "cc280000-0000-4000-8000-000000000060", "method": "expanded-v1", "to_date": "2026-10-01", "horizon": 28, "output": {"model": "naive", "forecast": []}, "source": {"private_email": "DO-NOT-SEND@example.com", "unit_cost": "99", "transactions": ["private"]}}, "output": {"status": "available", "lead_time": {"days": 3, "forecast": "3.001", "quantile": "4.125", "target": "4.125", "safety_stock": "1.124"}, "protection": {"days": 7, "forecast": "3.001", "quantile": "4.125", "target": "8.125", "safety_stock": "1.124"}, "residual_count": 84, "positive_days": 90, "samples": 5000, "calibration": [{"private": "DO-NOT-SEND"}]}}'::jsonb from generate_series(0,1) n;
create function pg_temp.preview() returns jsonb language sql as $$select public.policy_explainer_preview(pg_temp.id(1),pg_temp.id(50))$$;
create function pg_temp.request(n integer default 70,q text default 'Why this maximum?') returns uuid language sql as $$select public.policy_explainer_request(pg_temp.id(1),pg_temp.id(50),pg_temp.id(n),q,'en',pg_temp.preview()->>'fingerprint',true)$$;
select pg_temp.login(10);set local role authenticated;
select is(pg_temp.preview()#>>'{evidence,lead_threshold,target}','4.125','decimal evidence is exact');
select ok(position('DO-NOT-SEND' in pg_temp.preview()::text)=0,'raw transactions, account and calibration details excluded');
select ok(not(pg_temp.preview()->'evidence' ? 'policy_id'),'provider summary excludes source identifiers');
select throws_ok($$select pg_temp.request()$$,'MQ403',null,'organization opt-in defaults off');
select throws_ok($$insert into public.policy_explainer_settings values(pg_temp.id(1),true,now(),pg_temp.id(10))$$,'42501',null,'no direct settings write');
select pg_temp.login(11);
select throws_ok($$select public.policy_explainer_configure(pg_temp.id(1),true)$$,'MQ403',null,'planner cannot opt in');
select pg_temp.login(14);
select throws_ok($$select pg_temp.preview()$$,'MQ404',null,'foreign tenant cannot preview');
select is((select count(*) from public.policy_explainer_settings),0::bigint,'foreign tenant cannot inspect settings');
select pg_temp.login(13);
select lives_ok($$select pg_temp.preview()$$,'permitted branch previews');
select throws_ok($$select public.policy_explainer_preview(pg_temp.id(1),pg_temp.id(51))$$,'MQ404',null,'branch cannot preview other location');
select throws_ok($$select pg_temp.request()$$,'MQ403',null,'branch role cannot generate');
select pg_temp.login(10);
select public.policy_explainer_configure(pg_temp.id(1),true);
select throws_ok($$select public.policy_explainer_request(pg_temp.id(1),pg_temp.id(50),pg_temp.id(70),'Why?','en',repeat('0',64),true)$$,'MQ409',null,'changed preview rejected');
select throws_ok($$select public.policy_explainer_request(pg_temp.id(1),pg_temp.id(50),pg_temp.id(70),'Why?','en',pg_temp.preview()->>'fingerprint',false)$$,'MQ422',null,'sharing confirmation required');
select throws_ok($$select pg_temp.request(70,repeat('x',2001))$$,'MQ422',null,'question bounded');
create temporary table saved as select pg_temp.request() id;
grant select on saved to service_role;
select is(pg_temp.request(),(select id from saved),'identical request stable');
select throws_ok($$select pg_temp.request(70,'different')$$,'MQ409',null,'conflicting retry rejected');
select throws_ok($$select pg_temp.request(71)$$,'MQ429',null,'per-editor minute limit enforced');
select throws_ok($$update public.policy_explanations set status='succeeded'$$,'42501',null,'member cannot forge publication');
select throws_ok($$select public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')$$,'42501',null,'dispatch is server-only');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{}','claude-sonnet-5-5',null)$$,'42501',null,'publication is server-only');
select pg_temp.login(11);
select lives_ok($$select pg_temp.request(72)$$,'second editor request permitted');
select pg_temp.login(15);
select throws_ok($$select pg_temp.request(73)$$,'MQ429',null,'organization concurrency bounded');
reset role;set local role service_role;
select is(public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')->>'dispatch','true','first dispatch claims exactly once');
select is(public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')->>'dispatch','false','repeated dispatch does not resend');
select throws_ok($$select public.policy_explainer_dispatch((select id from saved),pg_temp.id(14),'claude-sonnet-5-5')$$,'MQ404',null,'wrong actor cannot dispatch');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"bad","references":["unknown"]}]}','claude-sonnet-5-5',null)$$,'MQ422',null,'unknown evidence references fail database validation');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[]}','claude-sonnet-5-5',null)$$,'MQ422',null,'empty answer blocked');
reset role;
update public.memberships set role='viewer' where user_id=pg_temp.id(10);
set local role service_role;
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"Three days.","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'MQ403',null,'revocation before publication blocks answer');
reset role;update public.memberships set role='owner' where user_id=pg_temp.id(10);
set local role authenticated;select pg_temp.login(10);select public.policy_explainer_configure(pg_temp.id(1),false);
reset role;set local role service_role;
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"Three days.","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'MQ403',null,'disable before publication blocks answer');
reset role;set local role authenticated;select pg_temp.login(10);select public.policy_explainer_configure(pg_temp.id(1),true);
reset role;set local role service_role;
select lives_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"Three days.","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'authorized answer published');
select lives_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),'{"paragraphs":[{"text":"Three days.","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'completion retry immutable');
select throws_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),null,null,'provider_error')$$,'MQ409',null,'terminal answer cannot be overwritten');
select throws_ok($$select * from public.policy_explanations$$,'42501',null,'service key has no direct table grant');
reset role;set local role authenticated;select pg_temp.login(10);select public.policy_explainer_configure(pg_temp.id(1),false);
select is(pg_temp.request(),(select id from saved),'completed reservation retry survives opt-out');
reset role;set local role service_role;
select is(public.policy_explainer_dispatch((select id from saved),pg_temp.id(10),'claude-sonnet-5-5')->>'dispatch','false','completed retry after opt-out never resends');
select lives_ok($$select public.policy_explainer_complete((select id from saved),pg_temp.id(10),' {"paragraphs":[{"text":"Three days.","references":["policy_inputs"]}]}','claude-sonnet-5-5',null)$$,'identical completed publication remains stable after opt-out');
reset role;set local role authenticated;select pg_temp.login(10);select public.policy_explainer_configure(pg_temp.id(1),true);

reset role;set local role authenticated;select pg_temp.login(12);
select is((select count(*) from public.policy_explanations),2::bigint,'viewer sees saved location-scoped history');
select pg_temp.login(13);
select is((select count(*) from public.policy_explanations),2::bigint,'permitted branch sees history');
reset role;delete from public.membership_locations where user_id=pg_temp.id(13);
set local role authenticated;
select is((select count(*) from public.policy_explanations),0::bigint,'location revocation removes rows and count');
select pg_temp.login(14);
select is((select count(*) from public.policy_explanations),0::bigint,'other organization cannot read results');
reset role;
update public.inventory_policies set unit=null where id=pg_temp.id(51);
set local role authenticated;select pg_temp.login(10);
select throws_ok($$select public.policy_explainer_preview(pg_temp.id(1),pg_temp.id(51))$$,'MQ422',null,'unknown demand units unavailable');
reset role;update public.inventory_policies set unit='EA',evidence=jsonb_set(evidence,'{forecast,method}','"regional-v1"') where id=pg_temp.id(51);
set local role authenticated;
select throws_ok($$select public.policy_explainer_preview(pg_temp.id(1),pg_temp.id(51))$$,'MQ422',null,'prepared group policies excluded');
reset role;
-- Quotas count attempts, including failures, and are enforced in Postgres.
update public.policy_explanations set created_at=clock_timestamp()-interval '4 minutes';
insert into public.policy_explanations(organization_id,location_id,policy_id,policy_run_id,forecast_run_id,item_id,request_id,requested_by,question,locale,evidence,fingerprint,created_at)
 select organization_id,location_id,policy_id,policy_run_id,forecast_run_id,item_id,pg_temp.id(100+n),requested_by,question,locale,evidence,fingerprint,date_trunc('day',clock_timestamp()) from public.policy_explanations cross join generate_series(1,19) n where id=(select id from saved);
set local role authenticated;select pg_temp.login(10);
select throws_ok($$select pg_temp.request(80)$$,'MQ429',null,'twenty daily attempts per editor');
reset role;
insert into public.policy_explanations(organization_id,location_id,policy_id,policy_run_id,forecast_run_id,item_id,request_id,requested_by,question,locale,evidence,fingerprint,created_at)
 select organization_id,location_id,policy_id,policy_run_id,forecast_run_id,item_id,pg_temp.id(200+n),pg_temp.id(11),question,locale,evidence,fingerprint,date_trunc('day',clock_timestamp()) from public.policy_explanations cross join generate_series(1,79) n where id=(select id from saved);
set local role authenticated;select pg_temp.login(15);
select throws_ok($$select pg_temp.request(81)$$,'MQ429',null,'one hundred daily attempts per organization');
reset role;
delete from public.planning_runs where id=pg_temp.id(30);
set local role authenticated;select pg_temp.login(10);
select is((select status from public.policy_explanations where id=(select id from saved)),'succeeded','source deletion preserves captured answer');
select is((select evidence#>>'{lead_threshold,target}' from public.policy_explanations where id=(select id from saved)),'4.125','source deletion preserves exact evidence');
reset role;
select is((select count(*) from public.open_orders where organization_id=pg_temp.id(1)),0::bigint,'no operational order writes');
select is((select count(*) from public.stock_snapshots where organization_id=pg_temp.id(1)),0::bigint,'no operational stock writes');
select * from finish();rollback;
